INSERT INTO `jobs` (`id`, `uuid`, `company_id`, `recruiter_id`, `title`, `slug`, `description`, `requirements`, `benefits`, `job_type`, `exp_level`, `min_salary`, `max_salary`, `currency`, `is_salary_negotiable`, `location_city`, `location_address`, `status`, `deadline`, `views_count`, `applications_count`, `published_at`, `created_at`, `updated_at`) VALUES
(1, UUID(), 1, 1, 'Fresher .NET Backend Developer', 'fresher-dotnet-backend-developer-fpt', 'Tham gia phát triển dự án chuyển đổi số cho khách hàng Nhật Bản và Mỹ bằng ASP.NET Core.', 'Nắm vững C#, OOP, SQL Server hoặc MySQL. Chăm chỉ, tinh thần học hỏi tốt.', 'Lương tháng 13, bảo hiểm FPT Care, đào tạo chứng chỉ Microsoft miễn phí.', 'FULL_TIME', 'FRESHER', 9000000, 14000000, 'VND', 0, 'Hà Nội', NULL, 'PUBLISHED', NOW() + INTERVAL 30 DAY, 450, 18, NOW() - INTERVAL 15 DAY, NOW() - INTERVAL 15 DAY, NOW()),
(2, UUID(), 1, 1, 'Senior .NET Core Microservices Engineer', 'senior-dotnet-core-engineer-fpt', 'Thiết kế và triển khai kiến trúc Microservices chịu tải cao cho hệ thống ngân hàng số.', 'Tối thiểu 4 năm kinh nghiệm .NET Core, Docker, Kubernetes, Kafka hoặc RabbitMQ.', 'Mức lương hấp dẫn đến 45 triệu, thưởng hiệu quả kinh doanh.', 'FULL_TIME', 'SENIOR', 30000000, 45000000, 'VND', 0, 'Hà Nội', NULL, 'PUBLISHED', NOW() + INTERVAL 30 DAY, 820, 12, NOW() - INTERVAL 15 DAY, NOW() - INTERVAL 15 DAY, NOW()),
(3, UUID(), 2, 2, 'Junior Frontend React Developer', 'junior-frontend-react-vng', 'Phát triển giao diện web cho hệ sinh thái ZaloPay và các cổng thanh toán số.', 'Có từ 1-2 năm kinh nghiệm với ReactJS, TypeScript, TailwindCSS và Webpack/Vite.', 'Cơm trưa miễn phí tại VNG Campus, phòng Gym hiện đại, bảo hiểm sức khỏe cao cấp.', 'FULL_TIME', 'JUNIOR', 15000000, 22000000, 'VND', 0, 'TP. Hồ Chí Minh', NULL, 'PUBLISHED', NOW() + INTERVAL 30 DAY, 950, 24, NOW() - INTERVAL 15 DAY, NOW() - INTERVAL 15 DAY, NOW()),
(4, UUID(), 2, 2, 'Backend Golang Engineer', 'backend-golang-engineer-vng', 'Xây dựng hệ thống chat và streaming dữ liệu thời gian thực hàng triệu CCU.', 'Thành thạo Golang, Goroutines, Redis Cache, gRPC và kiến trúc phân tán.', 'Thưởng hiệu quả sản phẩm, môi trường công nghệ kỳ lân.', 'FULL_TIME', 'MIDDLE', 25000000, 38000000, 'VND', 0, 'TP. Hồ Chí Minh', NULL, 'PUBLISHED', NOW() + INTERVAL 30 DAY, 640, 15, NOW() - INTERVAL 15 DAY, NOW() - INTERVAL 15 DAY, NOW()),
(5, UUID(), 3, 3, 'Java Spring Boot Software Engineer', 'java-spring-boot-engineer-viettel', 'Phát triển các giải pháp chính phủ điện tử và thành phố thông minh cho Viettel Solutions.', 'Tốt nghiệp đại học chuyên ngành CNTT, thành thạo Java, Spring Boot, Oracle/PostgreSQL.', 'Chế độ đãi ngộ quân đội, du lịch hàng năm, phụ cấp điện thoại.', 'FULL_TIME', 'MIDDLE', 20000000, 32000000, 'VND', 0, 'Hà Nội', NULL, 'PUBLISHED', NOW() + INTERVAL 30 DAY, 510, 16, NOW() - INTERVAL 15 DAY, NOW() - INTERVAL 15 DAY, NOW()),
(6, UUID(), 3, 3, 'Cloud DevOps Engineer', 'cloud-devops-engineer-viettel', 'Vận hành hạ tầng Viettel Cloud, tự động hóa CI/CD pipeline và giám sát Kubernetes.', 'Kinh nghiệm thực chiến với Kubernetes, Terraform, Docker, Prometheus & Grafana.', 'Cơ hội thăng tiến trở thành Tech Lead hạ tầng đám mây.', 'FULL_TIME', 'MIDDLE', 22000000, 35000000, 'VND', 0, 'Hà Nội', NULL, 'PUBLISHED', NOW() + INTERVAL 30 DAY, 430, 9, NOW() - INTERVAL 15 DAY, NOW() - INTERVAL 15 DAY, NOW()),
(7, UUID(), 4, 4, 'Fresher Data Engineer', 'fresher-data-engineer-one-mount', 'Xây dựng data pipeline thu thập và xử lý dữ liệu cho VinShop và VinID.', 'Thành thạo Python, SQL nâng cao, hiểu biết về Data Warehouse và Spark.', 'Làm việc tại Times City, môi trường trẻ trung, định hướng data-driven.', 'FULL_TIME', 'FRESHER', 10000000, 16000000, 'VND', 0, 'Hà Nội', NULL, 'PUBLISHED', NOW() + INTERVAL 30 DAY, 600, 22, NOW() - INTERVAL 15 DAY, NOW() - INTERVAL 15 DAY, NOW()),
(8, UUID(), 4, 4, 'Senior Full-Stack Developer', 'senior-fullstack-developer-one-mount', 'Phát triển ứng dụng OneHousing tích hợp hệ thống bản đồ số và bất động sản.', 'Thành thạo ReactJS và Node.js/NestJS hoặc Java. Tư duy sản phẩm xuất sắc.', 'Mức lương cạnh tranh thị trường, gói ESOP ưu đãi.', 'FULL_TIME', 'SENIOR', 35000000, 50000000, 'VND', 0, 'Hà Nội', NULL, 'PUBLISHED', NOW() + INTERVAL 30 DAY, 780, 14, NOW() - INTERVAL 15 DAY, NOW() - INTERVAL 15 DAY, NOW()),
(9, UUID(), 5, 5, 'Mobile Developer (Flutter)', 'mobile-flutter-developer-momo', 'Phát triển các tính năng thanh toán QR, miniapp trên siêu ứng dụng MoMo.', 'Kinh nghiệm với Flutter hoặc Native Android/iOS, hiểu biết về Reactive Programming.', 'Môi trường Fintech năng động, văn phòng chuẩn quốc tế tại Phú Mỹ Hưng.', 'FULL_TIME', 'JUNIOR', 16000000, 25000000, 'VND', 0, 'TP. Hồ Chí Minh', NULL, 'PUBLISHED', NOW() + INTERVAL 30 DAY, 890, 20, NOW() - INTERVAL 15 DAY, NOW() - INTERVAL 15 DAY, NOW()),
(10, UUID(), 5, 5, 'Database Administrator (MySQL/Redis)', 'dba-mysql-redis-momo', 'Tối ưu hóa hiệu năng, bảo trì và đảm bảo tính sẵn sàng 99.99% cho cụm database.', 'Ít nhất 3 năm kinh nghiệm DBA MySQL, Sharding, Replication, Performance Tuning.', 'Thưởng Tết và quý hấp dẫn, bảo hiểm quốc tế.', 'FULL_TIME', 'MIDDLE', 25000000, 40000000, 'VND', 0, 'TP. Hồ Chí Minh', NULL, 'PUBLISHED', NOW() + INTERVAL 30 DAY, 310, 8, NOW() - INTERVAL 15 DAY, NOW() - INTERVAL 15 DAY, NOW()),
(11, UUID(), 6, 6, 'Junior Software Engineer (.NET & Cloud)', 'junior-software-engineer-nab', 'Tham gia dự án hiện đại hóa ngân hàng số cho National Australia Bank.', 'Kinh nghiệm 1 năm với C#, REST API, có tư duy Clean Code và Unit Testing.', '100% tiếng Anh, làm việc tại tòa nhà hạng A Thủ Thiêm, laptop Mac M2/M3.', 'FULL_TIME', 'JUNIOR', 18000000, 28000000, 'VND', 0, 'TP. Hồ Chí Minh', NULL, 'PUBLISHED', NOW() + INTERVAL 30 DAY, 1120, 35, NOW() - INTERVAL 15 DAY, NOW() - INTERVAL 15 DAY, NOW()),
(12, UUID(), 6, 6, 'QA Automation Engineer', 'qa-automation-engineer-nab', 'Thiết kế automation test framework bằng Cypress hoặc Playwright cho web banking.', 'Kinh nghiệm kiểm thử tự động, am hiểu CI/CD và Agile/Scrum.', 'Chế độ làm việc linh hoạt Hybrid 2 ngày ở nhà/tuần.', 'FULL_TIME', 'MIDDLE', 22000000, 32000000, 'VND', 0, 'TP. Hồ Chí Minh', NULL, 'PUBLISHED', NOW() + INTERVAL 30 DAY, 480, 11, NOW() - INTERVAL 15 DAY, NOW() - INTERVAL 15 DAY, NOW()),
(13, UUID(), 7, 7, 'Backend Engineer (Go/Java)', 'backend-engineer-tiki', 'Phát triển hệ thống kho vận thông minh và xử lý đơn hàng TikiNOW.', 'Thành thạo một trong các ngôn ngữ Go, Java, Python. Nắm vững cấu trúc dữ liệu.', 'Cơ hội giải quyết bài toán quy mô lớn hàng triệu đơn hàng mỗi ngày.', 'FULL_TIME', 'MIDDLE', 20000000, 35000000, 'VND', 0, 'TP. Hồ Chí Minh', NULL, 'PUBLISHED', NOW() + INTERVAL 30 DAY, 720, 19, NOW() - INTERVAL 15 DAY, NOW() - INTERVAL 15 DAY, NOW()),
(14, UUID(), 7, 7, 'Frontend Developer (Next.js)', 'frontend-developer-nextjs-tiki', 'Xây dựng trải nghiệm mua sắm mượt mà trên web Tiki.vn với Server-Side Rendering.', 'Thành thạo Next.js, React, Web Vitals và kỹ thuật tối ưu hóa tải trang.', 'Giảm giá đặc biệt khi mua hàng trên Tiki, bảo hiểm sức khỏe VIP.', 'FULL_TIME', 'JUNIOR', 15000000, 22000000, 'VND', 0, 'TP. Hồ Chí Minh', NULL, 'PUBLISHED', NOW() + INTERVAL 30 DAY, 640, 17, NOW() - INTERVAL 15 DAY, NOW() - INTERVAL 15 DAY, NOW()),
(15, UUID(), 8, 8, 'Software Engineer Intern (All Tracks)', 'software-engineer-intern-kms', 'Chương trình thực tập 3 tháng có lương dành cho sinh viên năm cuối xuất sắc.', 'Nền tảng OOP tốt với một trong các ngôn ngữ: Java, C#, JavaScript, Python.', 'Phụ cấp thực tập hấp dẫn, cơ hội trở thành nhân viên chính thức sau 3 tháng.', 'INTERNSHIP', 'INTERN', 4000000, 6000000, 'VND', 0, 'TP. Hồ Chí Minh', NULL, 'PUBLISHED', NOW() + INTERVAL 30 DAY, 1540, 48, NOW() - INTERVAL 15 DAY, NOW() - INTERVAL 15 DAY, NOW()),
(16, UUID(), 8, 8, 'Full-Stack Engineer (React & Java)', 'fullstack-engineer-react-java-kms', 'Phát triển sản phẩm SaaS cho thị trường Mỹ và Châu Âu.', 'Kinh nghiệm cả Frontend React và Backend Spring Boot, làm việc độc lập tốt.', 'Môi trường nói tiếng Anh, trợ cấp học tập chứng chỉ AWS.', 'FULL_TIME', 'MIDDLE', 22000000, 34000000, 'VND', 0, 'TP. Hồ Chí Minh', NULL, 'PUBLISHED', NOW() + INTERVAL 30 DAY, 560, 13, NOW() - INTERVAL 15 DAY, NOW() - INTERVAL 15 DAY, NOW()),
(17, UUID(), 9, 9, 'Senior .NET Developer', 'senior-dotnet-developer-nashtech', 'Phát triển ứng dụng đám mây trên nền tảng Microsoft Azure cho tập đoàn tài chính Anh.', 'Tối thiểu 3 năm kinh nghiệm .NET Core, Azure DevOps, Entity Framework Core.', 'Gói bảo hiểm sức khỏe gia đình, thưởng dự án định kỳ.', 'FULL_TIME', 'SENIOR', 28000000, 42000000, 'VND', 0, 'TP. Hồ Chí Minh', NULL, 'PUBLISHED', NOW() + INTERVAL 30 DAY, 630, 10, NOW() - INTERVAL 15 DAY, NOW() - INTERVAL 15 DAY, NOW()),
(18, UUID(), 9, 9, 'Fresher Java Software Engineer', 'fresher-java-software-engineer-nashtech', 'Chương trình NashTech Fresher Academy đào tạo nâng cao và phân bổ vào dự án thực tế.', 'Tốt nghiệp chuyên ngành CNTT, nắm vững Java Core, SQL và tiếng Anh đọc hiểu.', 'Hỗ trợ học phí đào tạo ban đầu, ký hợp đồng chính thức sau khóa học.', 'FULL_TIME', 'FRESHER', 8500000, 12000000, 'VND', 0, 'TP. Hồ Chí Minh', NULL, 'PUBLISHED', NOW() + INTERVAL 30 DAY, 890, 26, NOW() - INTERVAL 15 DAY, NOW() - INTERVAL 15 DAY, NOW()),
(19, UUID(), 10, 10, 'Software Engineer (AI & Computer Vision)', 'software-engineer-ai-axon', 'Phát triển thuật toán xử lý video và nhận diện hành vi trên các camera an ninh thông minh.', 'Thành thạo Python hoặc C++, am hiểu Deep Learning, OpenCV, Docker.', 'Lương bổng theo chuẩn công ty công nghệ Mỹ, chính sách thưởng cổ phiếu.', 'FULL_TIME', 'MIDDLE', 30000000, 50000000, 'VND', 0, 'TP. Hồ Chí Minh', NULL, 'PUBLISHED', NOW() + INTERVAL 30 DAY, 710, 14, NOW() - INTERVAL 15 DAY, NOW() - INTERVAL 15 DAY, NOW()),
(20, UUID(), 10, 10, 'Cloud Backend Engineer (Go / AWS)', 'cloud-backend-engineer-axon', 'Xây dựng các microservices đám mây trên AWS lưu trữ hàng petabyte video chứng cứ.', 'Thành thạo Golang, AWS (ECS, S3, DynamoDB), Kafka và gRPC.', 'Văn phòng chuẩn quốc tế, trang thiết bị tối tân, cơm trưa nhà hàng.', 'FULL_TIME', 'SENIOR', 35000000, 55000000, 'VND', 0, 'TP. Hồ Chí Minh', NULL, 'PUBLISHED', NOW() + INTERVAL 30 DAY, 820, 16, NOW() - INTERVAL 15 DAY, NOW() - INTERVAL 15 DAY, NOW()),
(21, UUID(), 1, 1, 'Intern .NET Backend Developer', 'intern-dotnet-backend-fpt', 'Dành cho sinh viên năm 3-4 mong muốn học hỏi chuyên sâu về kiến trúc C# .NET.', 'Biết viết code C# cơ bản, ham học hỏi, có trách nhiệm cao.', 'Trợ cấp thực tập, hỗ trợ đóng dấu đồ án tốt nghiệp.', 'INTERNSHIP', 'INTERN', 3500000, 5500000, 'VND', 0, 'Đà Nẵng', NULL, 'PUBLISHED', NOW() + INTERVAL 30 DAY, 980, 31, NOW() - INTERVAL 15 DAY, NOW() - INTERVAL 15 DAY, NOW()),
(22, UUID(), 2, 2, 'Fresher Frontend Web (React)', 'fresher-frontend-react-vng', 'Gia nhập đội ngũ phát triển sản phẩm Zing MP3 phiên bản Web mới.', 'Nắm vững HTML, CSS, JavaScript, đã từng làm ít nhất 1 dự án bằng ReactJS.', 'Trải nghiệm văn hóa làm việc trẻ trung tại VNG Campus.', 'FULL_TIME', 'FRESHER', 9000000, 14000000, 'VND', 0, 'TP. Hồ Chí Minh', NULL, 'PUBLISHED', NOW() + INTERVAL 30 DAY, 750, 28, NOW() - INTERVAL 15 DAY, NOW() - INTERVAL 15 DAY, NOW()),
(23, UUID(), 4, 4, 'Fresher Android Developer (Kotlin)', 'fresher-android-developer-one-mount', 'Tham gia phát triển app VinShop phục vụ hàng trăm ngàn tạp hóa tại Việt Nam.', 'Có kiến thức tốt về Kotlin, Android SDK, MVVM Architecture.', 'Cơ hội học hỏi từ các chuyên gia hàng đầu từ Google, Grab gia nhập One Mount.', 'FULL_TIME', 'FRESHER', 9500000, 14500000, 'VND', 0, 'Hà Nội', NULL, 'PUBLISHED', NOW() + INTERVAL 30 DAY, 530, 19, NOW() - INTERVAL 15 DAY, NOW() - INTERVAL 15 DAY, NOW()),
(24, UUID(), 6, 6, 'Intern QA Engineer', 'intern-qa-engineer-nab', 'Học việc kiểm thử phần mềm thủ công và bước đầu tiếp cận kiểm thử tự động tại NAB.', 'Cẩn thận, tỉ mỉ, tiếng Anh giao tiếp khá.', 'Môi trường ngân hàng quốc tế, mentor nhiệt tình.', 'INTERNSHIP', 'INTERN', 5000000, 7000000, 'VND', 0, 'TP. Hồ Chí Minh', NULL, 'PUBLISHED', NOW() + INTERVAL 30 DAY, 690, 25, NOW() - INTERVAL 15 DAY, NOW() - INTERVAL 15 DAY, NOW()),
(25, UUID(), 8, 8, 'Junior DevOps Specialist', 'junior-devops-specialist-kms', 'Hỗ trợ xây dựng và bảo trì CI/CD pipeline cho các nhóm dự án phần mềm.', '1 năm kinh nghiệm với Docker, Linux, bash script và một trong các cloud AWS/Azure.', 'Môi trường học tập cởi mở, khuyến khích thi các chứng chỉ quốc tế.', 'FULL_TIME', 'JUNIOR', 14000000, 21000000, 'VND', 0, 'TP. Hồ Chí Minh', NULL, 'PUBLISHED', NOW() + INTERVAL 30 DAY, 410, 11, NOW() - INTERVAL 15 DAY, NOW() - INTERVAL 15 DAY, NOW());
